{% extends "base.html" %}

{% block title %}note記事一覧{% endblock %}

{% block content %}
<div class="container mt-4">
    <h1 class="mb-4">{{ config['APP_TITLE'] }}</h1>

    <div class="button-container mb-3">
        <a href="{{ url_for('index') }}" class="btn btn-primary">全て</a>
        {% for subject in subjects %}
            <a href="{{ url_for('index', subject=subject) }}" class="btn btn-outline-primary">{{ subject }}</a>
        {% endfor %}
    </div>

    <p>全{{ school_count }}件</p>

    <div id="school-list">
        {% for school in schools %}
            <div class="card mb-3">
                <div class="card-header">{{ school.name }}</div>
                <div class="card-body">
                    <div class="row">
                        {% for report in school.reports %}
                            <div class="col-md-3">
                                {% if report.note_url %}
                                    <a href="{{ report.note_url }}" target="_blank" class="btn btn-info btn-sm">{{ report.subject }}</a>
                                {% else %}
                                    <button class="btn btn-secondary btn-sm" disabled>{{ report.subject }}</button>
                                {% endif %}
                            </div>
                        {% endfor %}
                    </div>
                </div>
            </div>
        {% endfor %}
    </div>
</div>

<script>
document.addEventListener('DOMContentLoaded', function() {
    const buttons = document.querySelectorAll('.button-container .btn');
    const urlParams = new URLSearchParams(window.location.search);
    const currentSubject = urlParams.get('subject');

    buttons.forEach(button => {
        const buttonSubject = button.innerText;
        if ((!currentSubject && buttonSubject === '全て') || (currentSubject === buttonSubject)) {
            button.classList.remove('btn-outline-primary');
            button.classList.add('btn-primary');
        } else {
            button.classList.remove('btn-primary');
            button.classList.add('btn-outline-primary');
        }
    });
});
</script>

{% endblock %}



